// <auto-generated />
import axios from 'axios';
import type { AxiosInstance, AxiosRequestConfig, AxiosResponse, InternalAxiosRequestConfig } from 'axios';
import { ApiError, decodeText, errorMessage } from '../errors/ApiError';
import { ValidationError } from '../errors/ValidationError';
import { isXmlMediaType, parseXml, readProblemXml, xmlSuccessArm, type XmlOptions } from '../helpers/xml';
import type { ApiResult } from '../types/ApiResult';

class UnparseableBody {
  constructor(public readonly raw: string) {}
}

export type AxiosRequestInterceptor = (config: InternalAxiosRequestConfig) => InternalAxiosRequestConfig | Promise<InternalAxiosRequestConfig>;
export type AxiosResponseInterceptor = (response: AxiosResponse) => AxiosResponse | Promise<AxiosResponse>;

/**
 * A security scheme of an operation (the generated client passes them): a bearer token - http bearer, OAuth2, OpenID
 * Connect - from getAccessToken, or an API key from apiKeys (by the scheme's name in components.securitySchemes),
 * sent in the header, query parameter or cookie the scheme declares.
 */
export type SecurityScheme =
  | { readonly type: 'bearer' }
  | { readonly type: 'apiKey'; readonly scheme: string; readonly in: 'header' | 'query' | 'cookie'; readonly name: string };

export interface ApiClientOptions {
  /** The access token, sent as a bearer token with the operations that require one (http bearer, OAuth2, OpenID Connect). */
  getAccessToken?: () => string | Promise<string>;
  /** The API keys of the specification's apiKey security schemes, by scheme name: sent with the operations that require them. */
  apiKeys?: Record<string, string | (() => string | undefined | Promise<string | undefined>)>;
  defaultHeaders?: Record<string, string>;
  requestInterceptors?: AxiosRequestInterceptor[];
  responseInterceptors?: AxiosResponseInterceptor[];
}

export interface RequestOptions {
  body?: unknown;
  query?: Record<string, string | number | boolean | (string | number | boolean)[] | undefined>;
  headers?: Record<string, string | number | boolean | undefined>;
  /**
   * The operation's security schemes (the generated client passes them): [] for an anonymous operation, which sends
   * no credentials. Without it (a specification that declares no security) the access token is sent when there is one.
   */
  security?: readonly SecurityScheme[];
  signal?: AbortSignal;
  responseType?: 'json' | 'blob' | 'text';
  /** The media type of a file sent as the raw body (the generated client passes the declared one); else the file's own type. */
  contentType?: string;
  /** The result arms of the operation's union (the generated client passes them): a status it does not declare is folded into one it does. */
  arms?: readonly string[];
  /** An XML body (the generated client passes it): the Accept, how to write the request body and read the response. */
  xml?: XmlOptions;
}

export type StreamFraming = 'json-array' | 'sse' | 'json-lines' | 'json-seq' | 'multipart';

/** Releases a body reader; a stream that was not read to its end is cancelled first, so the connection is closed. */
async function releaseReader(reader: ReadableStreamDefaultReader<Uint8Array>, finished: boolean): Promise<void> {
  if (!finished) {
    await reader.cancel().catch(() => undefined);
  }

  reader.releaseLock();
}

/**
 * The longest record (an event, a JSON Lines line, a JSON Text Sequence record, a JSON array element, a multipart
 * part) a stream reader takes, in characters: a longer one - or a server that never ends one - is a RangeError, not
 * a buffer that grows until the tab or the process runs out of memory. Default: 16 MB. Settable.
 */
export const streamLimits = { maxRecordLength: 16 * 1024 * 1024 };

function guardRecord(length: number): void {
  if (length > streamLimits.maxRecordLength) {
    throw new RangeError(`A streamed record is longer than ${streamLimits.maxRecordLength} characters.`);
  }
}

/**
 * The body of one part of a multipart response - what follows its boundary: past the boundary's padding, the
 * part's headers (a part may have none) and the blank line after them. Null for the closing boundary and for a
 * part whose headers have not ended yet.
 */
function multipartBody(part: string): string | null {
  if (part.startsWith('--')) return null;
  const head = part.replace(/^[ \t]*\r\n/, '');
  if (head.startsWith('\r\n')) return head.substring(2).trim();
  const sep = head.indexOf('\r\n\r\n');
  return sep === -1 ? null : head.substring(sep + 4).trim();
}

async function* parseEventStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder, reviver?: (key: string, value: unknown) => unknown, itemEvents?: readonly string[]): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) { finished = true; break; }
      buffer += decoder.decode(value, { stream: true }).replace(/\r/g, '');
      let sep: number;
      while ((sep = buffer.indexOf('\n\n')) !== -1) {
        guardRecord(sep);
        const rawEvent = buffer.substring(0, sep);
        buffer = buffer.substring(sep + 2);
        const lines = rawEvent.split('\n');
        const eventLine = lines.find((l) => l.startsWith('event:'));
        const eventType = eventLine ? eventLine.slice(6).trim() : 'message';
        const data = lines
          .filter((l) => l.startsWith('data:'))
          .map((l) => l.slice(5).trimStart())
          .join('\n');
        // The item event is the unnamed one (or 'message', the same by the standard), and the ones the operation
        // names (x-sse-item-events): each must be an item. An event without data and any other named event (a
        // heartbeat, a control frame) are read past.
        if ((eventType !== 'message' && !itemEvents?.includes(eventType)) || data.trim().length === 0) continue;
        yield JSON.parse(data, reviver) as T;
      }
      guardRecord(buffer.length);
    }
  } finally {
    await releaseReader(reader, finished);
  }
}

/** The end (exclusive) of the JSON value that starts at `start`, or -1 while the text holds only part of it. A number or a literal at the text's end is complete only when the stream is. */
function scanJsonValue(text: string, start: number, atEnd: boolean): number {
  const first = text.charAt(start);
  if (first === '{' || first === '[') {
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < text.length; i++) {
      const ch = text.charAt(i);
      if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
      if (ch === '"') inStr = true;
      else if (ch === '{' || ch === '[') depth++;
      else if (ch === '}' || ch === ']') { depth--; if (depth === 0) return i + 1; }
    }
    return -1;
  }
  if (first === '"') {
    let esc = false;
    for (let i = start + 1; i < text.length; i++) {
      const ch = text.charAt(i);
      if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') return i + 1;
    }
    return -1;
  }
  let i = start;
  while (i < text.length && !' \t\r\n,]}'.includes(text.charAt(i))) i++;
  return i < text.length || atEnd ? i : -1;
}

/** Reads a JSON array one element at a time; values that are not wrapped in an array are read one after the other. */
async function* parseJsonArrayStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let pos = 0;
  let finished = false;
  let inArray: boolean | undefined;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) finished = true; else buffer += decoder.decode(value, { stream: true });
      let ended = false;
      while (true) {
        while (pos < buffer.length && ' \t\r\n,'.includes(buffer.charAt(pos))) pos++;
        if (pos >= buffer.length) break;
        if (inArray === undefined) { inArray = buffer.charAt(pos) === '['; if (inArray) { pos++; continue; } }
        if (inArray && buffer.charAt(pos) === ']') { ended = true; break; }
        const end = scanJsonValue(buffer, pos, done);
        if (end === -1) break;
        guardRecord(end - pos);
        yield JSON.parse(buffer.substring(pos, end)) as T;
        pos = end;
      }
      if (ended || done) break;
      if (pos > 0) { buffer = buffer.substring(pos); pos = 0; }
      guardRecord(buffer.length);
    }
  } finally {
    await releaseReader(reader, finished);
  }
}

/** Reads JSON Lines: one value per line, blank lines skipped, a last line without its newline included. */
async function* parseJsonLinesStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) { finished = true; break; }
      buffer += decoder.decode(value, { stream: true });
      let nl: number;
      while ((nl = buffer.indexOf('\n')) !== -1) {
        guardRecord(nl);
        const line = buffer.substring(0, nl).trim();
        buffer = buffer.substring(nl + 1);
        if (line.length > 0) yield JSON.parse(line) as T;
      }
      guardRecord(buffer.length);
    }
    const rest = buffer.trim();
    if (rest.length > 0) yield JSON.parse(rest) as T;
  } finally {
    await releaseReader(reader, finished);
  }
}

/** Reads a JSON Text Sequence (RFC 7464): each record is a record separator (0x1E), the JSON text and a newline. */
async function* parseJsonSeqStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  const parse = (record: string): T | undefined => { const text = record.replace(/\x1e/g, '').trim(); return text.length > 0 ? JSON.parse(text) as T : undefined; };
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) { finished = true; break; }
      buffer += decoder.decode(value, { stream: true });
      let rs: number;
      while ((rs = buffer.indexOf('\x1e', 1)) !== -1) {
        guardRecord(rs);
        const item = parse(buffer.substring(0, rs));
        buffer = buffer.substring(rs);
        if (item !== undefined) yield item;
      }
      guardRecord(buffer.length);
      if (buffer.endsWith('\n')) { const item = parse(buffer); buffer = ''; if (item !== undefined) yield item; }
    }
    const last = parse(buffer);
    if (last !== undefined) yield last;
  } finally {
    await releaseReader(reader, finished);
  }
}

const httpErrorArms: readonly string[] = ['badRequest', 'unauthorized', 'forbidden', 'notFound', 'conflict', 'unprocessableEntity', 'tooManyRequests', 'clientError', 'serverError'];
const successArms = ['ok', 'created', 'accepted', 'noContent'] as const;

/**
 * Folds a result whose status the operation's union does not declare into one it does: an undeclared
 * error status into clientError (4xx) or serverError (5xx), an undeclared success into the declared one.
 */
function fitToArms<T>(result: ApiResult<T>, arms: readonly string[] | undefined): ApiResult<T> {
  if (!arms || arms.includes(result.status)) {
    return result;
  }

  if (httpErrorArms.includes(result.status) && 'error' in result && result.error instanceof ApiError) {
    const status = result.error.status >= 500 ? 'serverError' : 'clientError';
    return { status, error: result.error, response: result.response } as ApiResult<T>;
  }

  const declared = successArms.find((arm) => arms.includes(arm));
  if (declared === undefined || !(successArms as readonly string[]).includes(result.status)) {
    return result;
  }

  return declared === 'noContent'
    ? { status: 'noContent', response: result.response } as ApiResult<T>
    : { status: declared, data: ('data' in result ? result.data : undefined) as T, response: result.response } as ApiResult<T>;
}

/** A request's config with what the operation reads: every body is asked for as bytes (responseType), and bodyType says what to make of them. */
type BodyRequestConfig = AxiosRequestConfig & { bodyType?: 'json' | 'text' | 'arraybuffer' | 'auto' };

/** What the operation reads: its bodyType ('auto': whatever the Content-Type says), or - for a request made without one - its responseType. */
function bodyTypeOf(config: unknown): string | undefined {
  const request = config as BodyRequestConfig | undefined;
  return request?.bodyType ?? request?.responseType;
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly client: AxiosInstance;
  private readonly options: ApiClientOptions;

  constructor(baseUrl: string, options?: ApiClientOptions) {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
    this.options = options ?? {};
    this.client = axios.create({
      baseURL: this.baseUrl,
      validateStatus: () => true,
      paramsSerializer: { indexes: null },
      transformResponse: [function (this: InternalAxiosRequestConfig, data: unknown, headers?: Record<string, string>, status?: number) {
        const bodyType = bodyTypeOf(this);
        const rawContentType = String(headers?.['content-type'] ?? headers?.['Content-Type'] ?? '');
        // Every body arrives as bytes: its text is decoded by the charset the Content-Type names, which the
        // adapters do not agree on (Node's http adapter and the fetch adapter read every text as UTF-8)
        if ((this as BodyRequestConfig).bodyType !== 'arraybuffer' && (Object.prototype.toString.call(data) === '[object ArrayBuffer]' || ArrayBuffer.isView(data))) {
          data = decodeText(data as ArrayBuffer, rawContentType);
        }

        if (typeof data !== 'string' || data.length === 0) return data;
        if (bodyType === 'text') return data;
        const contentType = rawContentType.toLowerCase();
        const successReadAsJson = bodyType === 'json' && (status ?? 200) < 400;
        if (!successReadAsJson && !contentType.includes('application/json') && !contentType.includes('+json')) return data;
        try { return JSON.parse(data); } catch { return new UnparseableBody(data); }
      }],
    });

    if (this.options.defaultHeaders) {
      for (const [key, value] of Object.entries(this.options.defaultHeaders)) {
        this.client.defaults.headers.common[key] = value;
      }
    }

    for (const interceptor of this.options.requestInterceptors ?? []) {
      this.client.interceptors.request.use(interceptor);
    }

    for (const interceptor of this.options.responseInterceptors ?? []) {
      this.client.interceptors.response.use(interceptor);
    }
  }

  async request<T>(method: string, path: string, options?: RequestOptions): Promise<ApiResult<T>> {
    let data: unknown;
    const headers: Record<string, string> = {};

    if (options?.body !== undefined) {
      if (options.body instanceof FormData) {
        // Named, not left to the adapter: axios's fetch adapter in Node labels a FormData form-urlencoded.
        // Axios adds the boundary; in a browser it drops the header and the browser sets it.
        headers['Content-Type'] = 'multipart/form-data';
        data = options.body;
      } else if (options.body instanceof URLSearchParams) {
        headers['Content-Type'] = 'application/x-www-form-urlencoded';
        data = options.body;
      } else if (options.xml?.write) {
        headers['Content-Type'] = options.xml.contentType ?? 'application/xml; charset=utf-8';
        data = options.xml.write(options.body as never);
      } else if (options.body instanceof Blob) {
        const fileType = options.contentType ?? (options.body.type || 'application/octet-stream');
        headers['Content-Type'] = fileType;
        // Re-typed: an adapter may send the Blob's own type (Node's http adapter does)
        data = options.body.type === fileType ? options.body : new Blob([options.body], { type: fileType });
      } else {
        headers['Content-Type'] = options.contentType ?? 'application/json';
        data = options.body;
      }
    }

    for (const [key, value] of Object.entries(await this.credentials(options?.security, 'headers'))) {
      headers[key] = value;
    }

    const params = { ...options?.query, ...(await this.credentials(options?.security, 'query')) };

    if (options?.headers) {
      for (const [key, value] of Object.entries(options.headers)) {
        if (value !== undefined) {
          headers[key] = String(value);
        }
      }
    }

    if (options?.xml?.accept) {
      headers['Accept'] = options.xml.accept;
    }

    const response = await this.client.request<T>({
      method,
      url: path,
      data,
      params,
      headers,
      signal: options?.signal,
      responseType: 'arraybuffer',
      bodyType: options?.responseType === 'blob' ? 'arraybuffer' : options?.responseType ?? 'auto',
    } as BodyRequestConfig);

    if (Object.prototype.toString.call(response.data) === '[object ArrayBuffer]' || ArrayBuffer.isView(response.data)) {
      const bytes = response.data as unknown as ArrayBuffer;
      const fileType = String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '');
      (response as { data: unknown }).data = response.status >= 200 && response.status < 300 && typeof Blob !== 'undefined'
        ? new Blob([bytes], fileType ? { type: fileType } : undefined)
        : decodeText(bytes, fileType);
    }

    return fitToArms(await this.handleResponse<T>(response, options?.xml), options?.arms);
  }

  // A stream goes through the axios instance like every request - the default headers, the access token and the
  // request and response interceptors apply - with axios' fetch adapter, whose 'stream' response is the body's
  // ReadableStream (axios 1.7 or later).
  async *requestStream<T>(method: string, path: string, options?: RequestOptions, framing: StreamFraming = 'json-array', sseItemEvents?: readonly string[]): AsyncGenerator<T> {
    const headers: Record<string, string> = {};
    for (const [key, value] of Object.entries(await this.credentials(options?.security, 'headers'))) {
      headers[key] = value;
    }

    const params = { ...options?.query, ...(await this.credentials(options?.security, 'query')) };

    if (options?.headers) {
      for (const [key, value] of Object.entries(options.headers)) {
        if (value !== undefined) {
          headers[key] = String(value);
        }
      }
    }

    let data: unknown;
    if (options?.body !== undefined) {
      headers['Content-Type'] = 'application/json';
      data = options.body;
    }

    const response = await this.client.request<ReadableStream<Uint8Array> | undefined>({
      method,
      url: path,
      data,
      params,
      headers,
      signal: options?.signal,
      adapter: 'fetch',
      responseType: 'stream',
    });

    if (response.status < 200 || response.status >= 300) {
      // The error body is read like any error body: as text, then a ProblemDetails / model / JSON string, or text
      const text = response.data ? decodeText(await new Response(response.data).arrayBuffer(), String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '')) : '';
      const result = await this.handleResponse<T>({ ...response, data: text, config: { ...response.config, responseType: 'text' } } as unknown as AxiosResponse<T>);
      if ('error' in result) {
        throw result.error;
      }

      throw new ApiError(response.status, response.statusText, 'Stream request failed', response);
    }

    const reader = response.data?.getReader();
    if (!reader) {
      throw new ApiError(0, 'NoBody', 'Response body is empty', response);
    }

    const decoder = new TextDecoder();

    if (framing === 'sse') {
      yield* parseEventStream<T>(reader, decoder, undefined, sseItemEvents);
      return;
    }

    if (framing === 'multipart') {
      const contentType = String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '');
      const m = /boundary=("?)([^";]+)\1/i.exec(contentType);
      // Without a boundary the parts cannot be found: an error, not a guess
      if (!m) throw new Error('A multipart/mixed response without a boundary in its Content-Type cannot be split into its parts.');
      const delimiter = '--' + m[2];
      let buf = '';
      let finished = false;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            finished = true;
            // A last part the stream ended on without its closing boundary (the server failed mid-stream): what it sent is yielded
            if (buf.startsWith(delimiter)) {
              const bodyText = multipartBody(buf.substring(delimiter.length)) ?? '';
              if (bodyText.length > 0 && scanJsonValue(bodyText, 0, true) === bodyText.length) yield JSON.parse(bodyText) as T;
            }
            break;
          }
          buf += decoder.decode(value, { stream: true });
          // Discard preamble (everything before the first delimiter boundary).
          const first = buf.indexOf(delimiter);
          if (first === -1) { if (buf.length > delimiter.length) buf = buf.substring(buf.length - delimiter.length); continue; }
          if (first > 0) buf = buf.substring(first);
          // Yield each complete part; buf always starts at a delimiter after this loop.
          while (buf.startsWith(delimiter)) {
            const partStart = delimiter.length;
            const next = buf.indexOf(delimiter, partStart);
            if (next === -1) {
              guardRecord(buf.length - partStart);
              // A part whose body is complete JSON is yielded now, not at the next boundary - a server that fails after it never sends one
              const pending = buf.substring(partStart);
              const pendingBody = multipartBody(pending) ?? '';
              if (pendingBody.length > 0 && pending.endsWith('\r\n') && scanJsonValue(pendingBody, 0, true) === pendingBody.length) { yield JSON.parse(pendingBody) as T; buf = ''; }
              break;
            }
            guardRecord(next - partStart);
            const part = buf.substring(partStart, next);
            buf = buf.substring(next);
            const bodyText = multipartBody(part);
            if (bodyText === null) continue;
            if (bodyText.length > 0) yield JSON.parse(bodyText) as T;
          }
        }
      } finally {
        await releaseReader(reader, finished);
      }
      return;
    }

    // JSON Lines, JSON Text Sequence, or a JSON array read one element at a time
    if (framing === 'json-lines') {
      yield* parseJsonLinesStream<T>(reader, decoder);
    } else if (framing === 'json-seq') {
      yield* parseJsonSeqStream<T>(reader, decoder);
    } else {
      yield* parseJsonArrayStream<T>(reader, decoder);
    }
  }

  /**
   * The credentials of an operation's security schemes that go in the headers (the access token as a bearer token, API
   * keys in a header or a cookie) or in the query. Without security schemes - a specification that declares no security -
   * the access token is sent when there is one; an anonymous operation ([]) sends none. A cookie API key is a Cookie
   * header, which browsers do not let a script set (there the browser sends its own cookies): Node only.
   */
  private async credentials(security: readonly SecurityScheme[] | undefined, place: 'headers' | 'query'): Promise<Record<string, string>> {
    const values: Record<string, string> = {};
    const cookies: string[] = [];
    for (const scheme of security ?? [{ type: 'bearer' } as const]) {
      if (scheme.type === 'bearer') {
        if (place === 'headers' && this.options.getAccessToken) {
          values['Authorization'] = `Bearer ${await this.options.getAccessToken()}`;
        }

        continue;
      }

      if ((scheme.in === 'query') !== (place === 'query')) {
        continue;
      }

      const key = this.options.apiKeys?.[scheme.scheme];
      const value = typeof key === 'function' ? await key() : key;
      if (value === undefined) {
        continue;
      }

      if (scheme.in === 'cookie') {
        cookies.push(`${scheme.name}=${encodeURIComponent(value)}`);
      } else {
        values[scheme.name] = value;
      }
    }

    if (cookies.length > 0) {
      values['Cookie'] = cookies.join('; ');
    }

    return values;
  }

  private async handleResponse<T>(response: AxiosResponse<T>, xml?: XmlOptions): Promise<ApiResult<T>> {
    // An XML body: read by the operation's mapping (no JSON handling)
    const responseContentType = String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '');
    const readXmlError = xml?.errors?.[String(response.status)] ?? xml?.errors?.['default'];
    if (readXmlError && (response.status < 200 || response.status >= 300) && isXmlMediaType(responseContentType) && typeof response.data === 'string') {
      try {
        (response as { data: unknown }).data = readXmlError(parseXml(response.data));
      } catch {
        // Not the declared model: the error arm gets the text
      }
    }

    if (xml?.read && response.status >= 200 && response.status < 300 && response.status !== 204 && response.status !== 205 && isXmlMediaType(responseContentType) && typeof response.data === 'string') {
      try {
        return { status: xmlSuccessArm(response.status), data: xml.read(parseXml(response.data)) as T, response } as ApiResult<T>;
      } catch (parseError) {
        return { status: 'parseError', error: parseError as Error, response };
      }
    }

    // 204 and 205 never carry a body; 304 neither (RFC 9110).
    if (response.status === 204 || response.status === 205) {
      return { status: 'noContent', response };
    }

    if (response.status === 304) {
      return { status: 'notModified', response };
    }

    if (response.status >= 200 && response.status < 300) {
      // A JSON body that failed to parse is carried as an UnparseableBody sentinel by
      // transformResponse (the only place the parse outcome is known). Surface it as a
      // discriminated 'parseError' instead of pretending the response succeeded. A JSON
      // string body that parsed fine (e.g. "token") is a plain string, not a sentinel.
      if (response.data instanceof UnparseableBody) {
        return {
          status: 'parseError',
          error: new Error('Response body could not be parsed as JSON'),
          response,
        };
      }

      // An empty body is no data (a text operation keeps its empty string).
      if ((response.data as unknown) === '' && bodyTypeOf(response.config) !== 'text') {
        (response as { data: unknown }).data = undefined;
      }
      const status = response.status === 201
        ? 'created' as const
        : response.status === 202
          ? 'accepted' as const
          : 'ok' as const;
      return { status, data: response.data, response };
    }

    // A 3xx axios did not follow (300, 305, 306, or maxRedirects: 0): no error - its body, if any.
    if (response.status >= 300 && response.status < 400) {
      const data = response.data instanceof UnparseableBody || response.data === '' ? undefined : response.data;
      return { status: 'redirection', data, response };
    }

    let errorBody: unknown = response.data instanceof UnparseableBody ? undefined : response.data;
    let errorBodyIsRawText = bodyTypeOf(response.config) === 'text' || bodyTypeOf(response.config) === 'arraybuffer';
    if (typeof Blob !== 'undefined' && errorBody instanceof Blob) {
      // A download's error arrives as a Blob (responseType 'blob'): read it like any other error body.
      errorBody = decodeText(await errorBody.arrayBuffer(), String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? ''));
      errorBodyIsRawText = true;
    }

    if (typeof errorBody === 'string') {
      const errorContentType = String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '').toLowerCase();
      if (errorBody.length === 0) {
        errorBody = undefined;
      } else if (errorContentType.includes('application/problem+xml')) {
        try {
          errorBody = readProblemXml(parseXml(errorBody));
        } catch {
          errorBody = undefined;
        }
      } else if (errorContentType.includes('application/json') || errorContentType.includes('+json')) {
        // Only a responseType 'text' request or a Blob left a JSON body unparsed; otherwise a string here is the
        // parsed value of a JSON-string body ("42" stays the string '42').
        if (errorBodyIsRawText) {
          try {
            errorBody = JSON.parse(errorBody);
          } catch {
            errorBody = undefined;
          }
        }
      } else if (!(errorContentType.startsWith('text/') || errorContentType.includes('application/xml') || errorContentType.includes('+xml'))) {
        // Neither JSON nor text (e.g. application/octet-stream, or no Content-Type): no body, as in the Fetch client.
        errorBody = undefined;
      }
    }

    const message = errorMessage(response.status, response.statusText, errorBody, String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? ''));

    if (response.status === 400) {
      // Always badRequest: a 400 without validation errors carries an empty errors map.
      const errors = errorBody !== null && typeof errorBody === 'object' && typeof (errorBody as { errors?: unknown }).errors === 'object' && (errorBody as { errors?: unknown }).errors !== null
        ? (errorBody as { errors: Record<string, string[]> }).errors
        : {};
      return {
        status: 'badRequest',
        error: new ValidationError(response.status, response.statusText, message, errors, response, errorBody),
        response,
      };
    }

    const apiError = new ApiError(response.status, response.statusText, message, response, errorBody);

    switch (response.status) {
      case 401:
        return { status: 'unauthorized', error: apiError, response };
      case 403:
        return { status: 'forbidden', error: apiError, response };
      case 404:
        return { status: 'notFound', error: apiError, response };
      case 409:
        return { status: 'conflict', error: apiError, response };
      case 422:
        return { status: 'unprocessableEntity', error: apiError, response };
      case 429:
        return { status: 'tooManyRequests', error: apiError, response };
      default:
        return response.status >= 400 && response.status < 500
          ? { status: 'clientError', error: apiError, response }
          : { status: 'serverError', error: apiError, response };
    }
  }
}